router.put("/invites/:id/respond", requireAuth, async (req, res) => {
  try {
    const userId = req.session.userId;
    const inviteId = req.params.id;
    const { response } = req.body;
    if (!["accepted", "declined"].includes(response)) {
      return res.status(400).json({ message: "Risposta non valida" });
    }
    const [invite] = await db.select().from(motoClubInvites).where(and(eq(motoClubInvites.id, inviteId), eq(motoClubInvites.userId, userId))).limit(1);
    if (!invite) return res.status(404).json({ message: "Invito non trovato" });
    await db.update(motoClubInvites).set({ status: response }).where(eq(motoClubInvites.id, inviteId));
    if (response === "accepted") {
      const [club] = await db.select().from(motoClubs).where(eq(motoClubs.id, invite.clubId)).limit(1);
      if (club) {
        const existing = await db.select().from(motoClubMembers).where(and(eq(motoClubMembers.clubId, invite.clubId), eq(motoClubMembers.userId, userId))).limit(1);
        if (existing.length > 0) {
          await db.update(motoClubMembers).set({ status: "active", joinedAt: /* @__PURE__ */ new Date() }).where(and(eq(motoClubMembers.clubId, invite.clubId), eq(motoClubMembers.userId, userId)));
        } else {
          await db.insert(motoClubMembers).values({ clubId: invite.clubId, userId, status: "active" });
        }
        let convId = club.conversationId;
        if (!convId) convId = await createClubConversation(invite.clubId, club.name);
        if (convId) await addMemberToConversation(convId, userId);
        await db.update(motoClubs).set({ activityScore: sql`activity_score + 2`, updatedAt: /* @__PURE__ */ new Date() }).where(eq(motoClubs.id, invite.clubId));
        await notifyTopMembersOfNewJoin(invite.clubId, userId, club.name);
      }
    }
    return res.json({ message: response === "accepted" ? "Sei entrato nel club!" : "Invito rifiutato" });
  } catch (e) {
    console.error("[PUT /invites/:id/respond]", e);
    return res.status(500).json({ message: "Errore interno" });
  }
});
