    const isCurrentlyOnline = user.lastLoginAt && new Date(user.lastLoginAt) >= fifteenMinutesAgo;
    const newLoginAt = isCurrentlyOnline ? /* @__PURE__ */ new Date("2020-01-01") : /* @__PURE__ */ new Date();
